public static Stack<int> ToStack(Node<int> chain)
{
    Stack<int> s = new Stack<int>();
    Node<int> pos = chain;
    while (pos != null)
    {
        s.Push(pos.GetValue());
        pos = pos.GetNext();
    }
    return s;
}

