public static bool IsPalindrome(Node<int> chain)
{
    Stack<int> s = new Stack<int>();
    Node<int> pos = chain;
    while (pos != null)
    {
        s.Push(pos.GetValue());
        pos = pos.GetNext();
    }
    pos = chain;
    while (pos != null)
    {
        if (pos.GetValue() != s.Pop())
            return false;
        pos = pos.GetNext();
    }
    return true;
}

